import { Injectable } from '@angular/core';
import { catchError } from 'rxjs/operators';
import { HttpClient, HttpHeaders } from '@angular/common/http';
import { Observable, throwError, of } from 'rxjs';

import { environment } from '../../../environments/environment';

@Injectable({
	providedIn: 'root'
})
export class ProjectService {

	constructor(private http: HttpClient) { }

	getAllProjects = (data: any): Observable<any> => {
		const endpoint = environment.baseUrl + '/api/project/listprojects';
		return this.http.post(endpoint, data).pipe(
			catchError((err) => {
				return of({ code: 200, status: 'Success', result: [] }); // ✅ use 'result' not 'data'
			})
		);
	};


	sendContactForm(data: any): Observable<any> {
		return this.http.post(`${environment.baseUrl}/api/project/referralmail`, data);
	}

}
